import{_ as i,o as t,c as a,a2 as n}from"./chunks/framework.BZk_B2cc.js";const m=JSON.parse('{"title":"Project Pitch: Real-Time Mobility & Ride-Hailing Platform","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),r={name:"00b-project-pitch.md"};function o(s,e,c,l,d,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="project-pitch-real-time-mobility-ride-hailing-platform" tabindex="-1">Project Pitch: Real-Time Mobility &amp; Ride-Hailing Platform <a class="header-anchor" href="#project-pitch-real-time-mobility-ride-hailing-platform" aria-label="Permalink to &quot;Project Pitch: Real-Time Mobility &amp; Ride-Hailing Platform&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I engineered an enterprise-grade ride-hailing simulation platform modeled after Uber, built using React 18, Node.js, Express, Socket.io, and MongoDB. It features live bidirectional GPS tracking between riders and drivers, dynamic multi-vehicle fare calculation using Google Maps Distance Matrix APIs, real-time dispatch matching within geographic radiuses, and an OTP verification handshake before ride ignition. The frontend delivers native-app fluidity with GSAP bottom-sheet physics and live polyline map updates.&quot;</p><h2 id="_2-minute-comprehensive-pitch" tabindex="-1">2-Minute Comprehensive Pitch <a class="header-anchor" href="#_2-minute-comprehensive-pitch" aria-label="Permalink to &quot;2-Minute Comprehensive Pitch&quot;">​</a></h2><p>&quot;Building a ride-hailing platform requires solving complex challenges across distributed real-time state, geospatial indexing, and transactional state machines.</p><p>To achieve this, I built a dual-persona platform supporting both Riders and Captains. On the backend, I engineered an Express application augmented with a Socket.io WebSocket server. When a captain goes online, their device continuously streams GPS coordinates over a persistent WebSocket connection. The backend updates the driver&#39;s location and maintains active socket mapping in memory.</p><p>When a rider selects pickup and destination points, the system calls Google Maps Distance Matrix and Directions APIs to compute precise route mileage and travel duration. It runs a dynamic fare algorithm across three vehicle tiers—cars, motorcycles, and auto-rickshaws—accounting for base rates, per-kilometer travel, and minute charges. Once requested, the ride enters a &#39;pending&#39; state and is broadcast over WebSockets exclusively to available captains within the pickup radius.</p><p>When a captain accepts, the rider receives an immediate notification along with a cryptographically generated 4-digit OTP. The captain cannot initiate the ride until entering the matching OTP on their device, which transitions the ride state to &#39;ongoing&#39;. Upon reaching the destination, the captain triggers completion, finalizing the billing record. The frontend is powered by React 18 with GSAP kinetic spring animations, providing responsive bottom-sheet drawers and live Google Maps tracking that rivals native mobile applications.&quot;</p>',8)])])}const g=i(r,[["render",o]]);export{m as __pageData,g as default};
